// Parse and validate the incoming request
const body = $input.item(0).json.body || {};

// Default values
const showDuration = parseInt(body.duration) || 60;
const minAvailability = body.availability || 'medium';
const outputFormat = body.format || 'json';
const gameCount = parseInt(body.gameCount) || null;

// Validate inputs
if (showDuration < 15 || showDuration > 180) {
  throw new Error('Show duration must be between 15 and 180 minutes');
}

if (!['high', 'medium', 'low'].includes(minAvailability)) {
  throw new Error('Availability must be high, medium, or low');
}

if (!['text', 'json', 'markdown'].includes(outputFormat)) {
  throw new Error('Format must be text, json, or markdown');
}

return {
  showDuration,
  minAvailability,
  outputFormat,
  gameCount,
  requestId: Date.now().toString(),
  timestamp: new Date().toISOString()
};

// Process the Python script output
const commandResult = $input.item(0).json;
const requestData = $node['Validate Request'].json;

// Check if command was successful
if (commandResult.exitCode !== 0) {
  throw new Error(`Scheduler failed: ${commandResult.stderr || 'Unknown error'}`);
}

const scheduleOutput = commandResult.stdout;
let parsedSchedule;

if (requestData.outputFormat === 'json') {
  try {
    parsedSchedule = JSON.parse(scheduleOutput);
  } catch (e) {
    throw new Error('Failed to parse JSON output from scheduler');
  }
} else {
  parsedSchedule = {
    format: requestData.outputFormat,
    content: scheduleOutput
  };
}

return {
  requestId: requestData.requestId,
  schedule: parsedSchedule,
  parameters: {
    duration: requestData.showDuration,
    availability: requestData.minAvailability,
    format: requestData.outputFormat,
    gameCount: requestData.gameCount
  },
  generatedAt: requestData.timestamp,
  success: true
};

